import pytest

import accounts


@pytest.fixture
def sample_users():
    return {
        1: {"email": "alice@example.com"},
        2: {"email": "bob@sub.domain.org"},
        3: {"email": "charlie@@double.at.com"},
        4: {"email": ""},
        5: {},  # user without an email key
    }


def test_email_domain_returns_correct_domain(sample_users):
    assert accounts.email_domain(sample_users, 1) == "example.com"
    assert accounts.email_domain(sample_users, 2) == "sub.domain.org"


def test_email_domain_missing_user_returns_none(sample_users):
    # user id 999 does not exist in the dictionary
    assert accounts.email_domain(sample_users, 999) is None


def test_email_domain_multiple_at_symbols(sample_users):
    # The function splits on '@' and returns the last segment
    assert accounts.email_domain(sample_users, 3) == "double.at.com"


def test_email_domain_empty_email_string(sample_users):
    # An empty email string results in an empty domain according to the implementation
    assert accounts.email_domain(sample_users, 4) == ""


def test_email_domain_missing_email_key_raises_keyerror(sample_users):
    # When the user dict lacks an "email" key, a KeyError is raised (current behaviour)
    with pytest.raises(KeyError):
        accounts.email_domain(sample_users, 5)

