import pytest

import frequency


def test_count_words_basic_sentence():
    text = "The quick brown fox jumps over the lazy dog the the"
    result = frequency.count_words(text)
    expected = {
        "the": 4,
        "quick": 1,
        "brown": 1,
        "fox": 1,
        "jumps": 1,
        "over": 1,
        "lazy": 1,
        "dog": 1,
    }
    assert result == expected


def test_count_words_case_insensitivity():
    text = "Hello hello HELLO HeLLo"
    result = frequency.count_words(text)
    assert result == {"hello": 4}


def test_count_words_empty_string():
    assert frequency.count_words("") == {}


def test_count_words_whitespace_variations():
    text = "   spaced   out\nnew\tline   "
    result = frequency.count_words(text)
    # split on any whitespace, lowercasing each token
    expected = {"spaced": 1, "out": 1, "new": 1, "line": 1}
    assert result == expected


def test_count_words_non_string_input_raises_attribute_error():
    with pytest.raises(AttributeError):
        # int does not have .lower(), causing AttributeError before any logic runs
        frequency.count_words(123)

