import pytest
import network

class DummyResult:
    def __init__(self, returncode: int):
        self.returncode = returncode


def test_ping_returns_exit_code(monkeypatch):
    """ping should return the returncode from subprocess.run."""
    def fake_run(cmd, shell, check):
        # Ensure the wrapper passes the expected flags
        assert shell is True
        assert check is False
        return DummyResult(0)
    monkeypatch.setattr(network.subprocess, "run", fake_run)
    assert network.ping("example.com") == 0


def test_ping_constructs_correct_command(monkeypatch):
    """The command string passed to subprocess.run must contain the host exactly once."""
    captured = {}
    def fake_run(cmd, shell, check):
        captured["cmd"] = cmd
        return DummyResult(1)
    monkeypatch.setattr(network.subprocess, "run", fake_run)
    rc = network.ping("my-host")
    assert rc == 1
    # The command should be exactly "ping -c 1 my-host"
    assert captured["cmd"] == "ping -c 1 my-host"


def test_ping_empty_host(monkeypatch):
    """An empty host should still produce a command; the function should not raise."""
    def fake_run(cmd, shell, check):
        # The command will end with a space after the flag
        assert cmd == "ping -c 1 "
        return DummyResult(2)
    monkeypatch.setattr(network.subprocess, "run", fake_run)
    assert network.ping("") == 2


def test_ping_non_string_host(monkeypatch):
    """If a non‑string is supplied, f‑string conversion should still work and the host appears in the command."""
    def fake_run(cmd, shell, check):
        assert cmd == "ping -c 1 12345"
        return DummyResult(3)
    monkeypatch.setattr(network.subprocess, "run", fake_run)
    # Pass an int; it will be converted to its string representation
    assert network.ping(12345) == 3


def test_ping_multiple_calls(monkeypatch):
    """Each call to ping should return the returncode from its own subprocess.run invocation."""
    returncodes = [0, 5, 255]
    calls = []
    def fake_run(cmd, shell, check):
        # Pop the next expected returncode
        rc = returncodes[len(calls)]
        calls.append(cmd)
        return DummyResult(rc)
    monkeypatch.setattr(network.subprocess, "run", fake_run)
    assert network.ping("a") == 0
    assert network.ping("b") == 5
    assert network.ping("c") == 255
    # Verify that three distinct commands were issued
    assert calls == ["ping -c 1 a", "ping -c 1 b", "ping -c 1 c"]
